/* ==========================================================================
   Relay — operations control room
   Local-only stylesheet. No external fonts or assets.
   ========================================================================== */

:root {
  color-scheme: dark;

  --bg: #0b0e12;
  --topbar: #0c1015;
  --rail: #0a0d11;
  --surface: #11161d;
  --surface-2: #151b23;
  --surface-3: #1a222c;
  --surface-4: #1f2834;

  --border: #232b35;
  --border-soft: #1c242e;
  --border-strong: #33404f;

  --text: #e7ecf2;
  --text-2: #b6c0cc;
  --muted: #8d99a6;
  --faint: #6b7785;

  --accent: #5aa2f7;
  --accent-bright: #7cb7ff;
  --accent-dim: rgba(90, 162, 247, 0.1);
  --accent-line: rgba(90, 162, 247, 0.38);

  --good: #4ec38c;
  --bad: #ef7268;
  --warn: #e3ad52;
  --teal: #56c2b1;

  --sev-critical: #f0655d;
  --sev-high: #e08b46;
  --sev-medium: #d8b44c;
  --sev-low: #819bb2;

  --radius: 4px;
  --topbar-h: 50px;
  --rail-w: 188px;

  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  height: 100%;
  overflow-x: hidden;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100%;
  overflow-x: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 13px;
  line-height: 1.45;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body.sheet-open {
  overflow: hidden;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

h1, h2, h3, p, dl, dd, dt, ol, ul {
  margin: 0;
}

ol, ul {
  padding: 0;
  list-style: none;
}

a {
  color: var(--accent);
  text-decoration: none;
}

[hidden] {
  display: none !important;
}

::selection {
  background: rgba(90, 162, 247, 0.32);
  color: #fff;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.icon-sprite {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}

.icon {
  width: 18px;
  height: 18px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon--sm {
  width: 15px;
  height: 15px;
}

.icon--xs {
  width: 11px;
  height: 11px;
  stroke-width: 1.9;
}

.skip-link {
  position: fixed;
  top: 8px;
  left: 8px;
  z-index: 200;
  padding: 8px 12px;
  border: 1px solid var(--accent);
  border-radius: 3px;
  background: #101820;
  color: var(--text);
  font-size: 12px;
  transform: translateY(-160%);
  transition: transform 120ms ease;
}

.skip-link:focus {
  transform: translateY(0);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

kbd {
  display: inline-block;
  min-width: 16px;
  padding: 1px 4px;
  border: 1px solid #34404e;
  border-bottom-color: #3f4c5c;
  border-radius: 2px;
  background: #141a21;
  color: #9aa6b4;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.35;
  text-align: center;
}

.mono {
  font-family: var(--mono);
}

/* ==========================================================================
   Shell, top bar, navigation rail
   ========================================================================== */

.shell {
  display: grid;
  grid-template-columns: var(--rail-w) minmax(0, 1fr);
  grid-template-rows: var(--topbar-h) minmax(0, 1fr);
  min-height: 100vh;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 18px;
  height: var(--topbar-h);
  padding: 0 16px;
  border-bottom: 1px solid var(--border);
  background: var(--topbar);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  flex: none;
}

.brand:focus-visible {
  outline-offset: 4px;
  border-radius: 2px;
}

.brand-mark {
  display: inline-flex;
  align-items: flex-end;
  justify-content: center;
  gap: 2px;
  width: 22px;
  height: 22px;
  padding: 4px;
  border: 1px solid rgba(90, 162, 247, 0.42);
  border-radius: 3px;
  background: rgba(90, 162, 247, 0.08);
}

.brand-mark i {
  display: block;
  width: 2px;
  border-radius: 1px;
  background: var(--accent);
}

.brand-mark i:nth-child(1) { height: 5px; opacity: 0.62; }
.brand-mark i:nth-child(2) { height: 11px; opacity: 0.82; }
.brand-mark i:nth-child(3) { height: 8px; }

.brand-name {
  font-size: 14.5px;
  font-weight: 620;
  letter-spacing: 0.015em;
}

.brand-tag {
  padding: 1px 4px;
  border: 1px solid var(--border-strong);
  border-radius: 2px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.09em;
}

.environment {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-left: 18px;
  border-left: 1px solid var(--border);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10.5px;
  white-space: nowrap;
}

.env-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-2);
}

.env-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--good);
}

.env-slash {
  color: #4c5865;
}

.env-region {
  color: var(--muted);
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-left: auto;
}

.global-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 26px;
  padding: 0 9px;
  border: 1px solid rgba(240, 101, 93, 0.34);
  border-radius: 3px;
  background: rgba(240, 101, 93, 0.07);
  color: #f2a29b;
  font-size: 11px;
  font-weight: 550;
  white-space: nowrap;
  transition: background-color 120ms ease, border-color 120ms ease;
}

.global-status:hover {
  border-color: rgba(240, 101, 93, 0.55);
  background: rgba(240, 101, 93, 0.11);
}

.status-dot {
  width: 6px;
  height: 6px;
  flex: none;
  border-radius: 50%;
  background: var(--bad);
  box-shadow: 0 0 0 3px rgba(239, 114, 104, 0.12);
  animation: status-pulse 3.2s ease-in-out infinite;
}

.global-status-detail {
  color: #b9827d;
  font-weight: 400;
}

@keyframes status-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.clock {
  display: flex;
  align-items: baseline;
  gap: 4px;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.clock-zone {
  color: var(--faint);
  font-size: 8.5px;
  letter-spacing: 0.08em;
}

.operator {
  display: flex;
  align-items: center;
  gap: 7px;
  padding-left: 13px;
  border-left: 1px solid var(--border);
}

.avatar {
  display: inline-grid;
  place-items: center;
  flex: none;
  border: 1px solid #34404e;
  border-radius: 50%;
  background: #1b2430;
  color: #c3cedb;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.02em;
}

.avatar--operator {
  width: 24px;
  height: 24px;
  border-color: #3a4858;
  background: #1d2733;
  font-size: 9px;
}

.avatar--small {
  width: 18px;
  height: 18px;
  font-size: 7.5px;
}

.operator-name {
  color: var(--text-2);
  font-size: 11px;
  white-space: nowrap;
}

.rail {
  position: sticky;
  top: var(--topbar-h);
  z-index: 35;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: calc(100vh - var(--topbar-h));
  padding: 12px 10px 10px;
  border-right: 1px solid var(--border);
  background: var(--rail);
}

.rail-scroll {
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: none;
}

.rail-scroll::-webkit-scrollbar {
  display: none;
}

.rail-label {
  margin: 12px 10px 6px;
  color: var(--faint);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.rail-label:first-child {
  margin-top: 2px;
}

.rail-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 33px;
  margin-bottom: 1px;
  padding: 0 10px;
  border: 0;
  border-radius: 3px;
  background: transparent;
  color: var(--text-2);
  font-size: 12px;
  text-align: left;
  transition: background-color 110ms ease, color 110ms ease;
}

.rail-item .icon {
  width: 17px;
  height: 17px;
  color: #7e8b99;
  transition: color 110ms ease;
}

.rail-item:hover {
  background: #12181f;
  color: var(--text);
}

.rail-item:hover .icon {
  color: #9dabba;
}

.rail-item.is-active {
  background: var(--accent-dim);
  color: #e2eeff;
  box-shadow: inset 2px 0 0 var(--accent);
}

.rail-item.is-active .icon {
  color: var(--accent);
}

.rail-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rail-badge {
  display: inline-grid;
  place-items: center;
  min-width: 19px;
  height: 17px;
  margin-left: auto;
  padding: 0 5px;
  border: 1px solid #2d3845;
  border-radius: 9px;
  background: #1a222c;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1;
}

.rail-item.is-active .rail-badge {
  border-color: rgba(90, 162, 247, 0.3);
  background: rgba(90, 162, 247, 0.12);
  color: #bad7fb;
}

.rail-group-system {
  margin-top: 20px;
  padding-top: 4px;
  border-top: 1px solid #161d25;
}

.rail-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  padding: 10px 8px 2px;
  border-top: 1px solid var(--border);
  min-width: 0;
}

.rail-foot-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.rail-foot-name {
  color: var(--text-2);
  font-size: 10.5px;
  line-height: 1.3;
}

.rail-foot-role {
  color: var(--faint);
  font-size: 9px;
  line-height: 1.4;
}

/* ==========================================================================
   Main frame
   ========================================================================== */

main {
  min-width: 0;
  max-width: 1720px;
  margin: 0 auto;
  padding: 20px 20px 30px;
}

main:focus {
  outline: none;
}

.page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.eyebrow {
  margin-bottom: 3px;
  color: var(--faint);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.title-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

h1 {
  font-size: 24px;
  font-weight: 620;
  letter-spacing: -0.025em;
  line-height: 1.1;
}

.scope-tag {
  display: inline-block;
  margin-top: 2px;
  padding: 1px 6px;
  border: 1px solid var(--border);
  border-radius: 2px;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.page-tools {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.live-chip,
.window-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 9px;
  border: 1px solid var(--border);
  border-radius: 3px;
  background: rgba(17, 22, 29, 0.55);
  color: var(--text-2);
  font-size: 10.5px;
  white-space: nowrap;
}

.live-chip {
  border-color: rgba(78, 195, 140, 0.22);
  background: rgba(78, 195, 140, 0.045);
}

.live-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--good);
  box-shadow: 0 0 0 3px rgba(78, 195, 140, 0.1);
}

.live-since {
  margin-left: 2px;
  color: var(--faint);
  font-size: 9.5px;
}

.window-chip {
  color: var(--muted);
}

.window-chip .icon {
  color: var(--faint);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--border-strong);
  border-radius: 3px;
  background: var(--surface-2);
  color: var(--text-2);
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 110ms ease, border-color 110ms ease, color 110ms ease, transform 60ms ease;
}

.btn:hover {
  border-color: #435264;
  background: var(--surface-3);
  color: var(--text);
}

.btn:active {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.btn-quiet {
  background: transparent;
  border-color: var(--border);
  color: var(--muted);
}

.btn-quiet:hover {
  background: var(--surface-2);
}

.btn-primary {
  border-color: #3f88e6;
  background: #4b96f3;
  color: #07111e;
  font-weight: 650;
}

.btn-primary:hover {
  border-color: #67a8f7;
  background: #64a7f7;
  color: #07111e;
}

.btn-secondary {
  background: transparent;
  border-color: var(--border-strong);
  color: var(--text-2);
}

.btn-secondary:hover {
  background: var(--surface-2);
}

.btn-label {
  line-height: 1;
}

.btn.is-spinning .icon {
  animation: spin 700ms linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ==========================================================================
   Panels and metrics
   ========================================================================== */

.panel {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
}

.metrics {
  margin-bottom: 12px;
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.metric {
  min-width: 0;
  padding: 13px 15px 12px;
  border-left: 1px solid var(--border);
}

.metric:first-child {
  border-left: 0;
}

.metric-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  min-height: 20px;
}

.metric-label {
  color: var(--muted);
  font-size: 9.5px;
  font-weight: 550;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  white-space: nowrap;
}

.spark {
  width: 62px;
  height: 20px;
  flex: none;
  overflow: visible;
  opacity: 0.9;
}

.spark-line {
  fill: none;
  stroke-width: 1.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.metric-value {
  margin: 4px 0 4px;
  color: var(--text);
  font-size: 25px;
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.12;
  white-space: nowrap;
}

.metric-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.delta {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  white-space: nowrap;
}

.delta .icon {
  width: 10px;
  height: 10px;
  stroke-width: 2.1;
}

.delta--good { color: var(--good); }
.delta--bad { color: var(--bad); }
.delta--neutral { color: var(--muted); }

.metric-context {
  overflow: hidden;
  color: var(--faint);
  font-size: 9.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
}

.panel-heading {
  min-width: 0;
}

.panel-head h2 {
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.005em;
  line-height: 1.3;
}

.panel-sub {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
}

.title-with-count {
  display: flex;
  align-items: center;
}

.micro-count {
  margin-left: 7px;
  padding: 0 5px;
  border: 1px solid var(--border-strong);
  border-radius: 2px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  line-height: 15px;
}

/* ==========================================================================
   Throughput chart
   ========================================================================== */

.throughput {
  margin-bottom: 12px;
}

.chart-head {
  min-height: 58px;
}

.chart-stats {
  display: flex;
  align-items: stretch;
  flex: none;
}

.chart-stat {
  display: flex;
  flex-direction: column;
  min-width: 64px;
  padding: 0 14px;
  border-left: 1px solid var(--border);
}

.chart-stat:first-child {
  padding-left: 0;
  border-left: 0;
}

.chart-stat:last-child {
  padding-right: 0;
}

.chart-stat dt {
  color: var(--faint);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  line-height: 1.4;
}

.chart-stat dd {
  color: var(--text);
  font-family: var(--mono);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.3;
}

.chart-stat-note {
  color: var(--faint);
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1.5;
  white-space: nowrap;
}

.chart-body {
  padding: 14px 16px 10px;
  overflow: hidden;
}

.chart {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  grid-template-rows: 168px 17px;
  column-gap: 6px;
}

.chart-y {
  position: relative;
  grid-column: 1;
  grid-row: 1;
}

.y-tick {
  position: absolute;
  right: 0;
  transform: translateY(-50%);
  color: var(--faint);
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1;
}

.chart-plot {
  position: relative;
  grid-column: 2;
  grid-row: 1;
  border-bottom: 1px solid #2a333f;
}

.chart-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.grid-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px solid #1a222b;
}

.grid-line:first-child {
  border-top-color: transparent;
}

.capacity-line {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 80%;
  z-index: 3;
  border-top: 1px dashed rgba(227, 173, 82, 0.42);
  pointer-events: none;
}

.capacity-line span {
  position: absolute;
  top: -13px;
  right: 1px;
  padding: 0 3px;
  background: var(--surface);
  color: #b99457;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.03em;
  line-height: 12px;
  text-transform: uppercase;
  white-space: nowrap;
}

.chart-bars {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  gap: 2px;
  padding: 0 2px;
}

.bar-col {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  flex: 1 1 0;
  width: 100%;
  height: 100%;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  -webkit-tap-highlight-color: transparent;
}

.bar {
  display: block;
  width: 100%;
  max-width: 16px;
  height: max(2px, var(--h));
  border-radius: 1px 1px 0 0;
  background: rgba(90, 162, 247, 0.42);
  transition: background-color 100ms ease, box-shadow 100ms ease;
}

.bar-col:hover .bar {
  background: rgba(124, 183, 255, 0.72);
}

.bar--hot {
  background: rgba(227, 173, 82, 0.55);
}

.bar-col:hover .bar--hot {
  background: rgba(236, 190, 111, 0.8);
}

.bar--now {
  background: var(--accent);
}

.bar-col.is-active .bar {
  box-shadow: 0 0 0 1px rgba(124, 183, 255, 0.2);
}

.bar-col:focus-visible {
  outline: none;
}

.bar-col:focus-visible .bar {
  outline: 2px solid var(--accent-bright);
  outline-offset: 2px;
  background: var(--accent);
}

.bar-tip {
  position: absolute;
  bottom: calc(var(--h) + 7px);
  left: 50%;
  z-index: 9;
  display: flex;
  align-items: baseline;
  gap: 5px;
  padding: 3px 6px;
  border: 1px solid var(--border-strong);
  border-radius: 2px;
  background: #1d2732;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.3;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 2px);
  transition: opacity 90ms ease, transform 90ms ease;
}

.bar-tip strong {
  color: var(--text);
  font-weight: 600;
}

.bar-col:hover .bar-tip,
.bar-col:focus-visible .bar-tip {
  opacity: 1;
  transform: translate(-50%, 0);
}

.bar-col:first-child .bar-tip {
  left: 0;
  transform: translate(0, 2px);
}

.bar-col:first-child:hover .bar-tip,
.bar-col:first-child:focus-visible .bar-tip {
  transform: translate(0, 0);
}

.bar-col:last-child .bar-tip {
  right: 0;
  left: auto;
  transform: translate(0, 2px);
}

.bar-col:last-child:hover .bar-tip,
.bar-col:last-child:focus-visible .bar-tip {
  transform: translate(0, 0);
}

.chart-x {
  display: flex;
  grid-column: 2;
  grid-row: 2;
  padding: 4px 2px 0;
}

.x-slot {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
}

.x-label {
  position: absolute;
  top: 0;
  left: 50%;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1;
  white-space: nowrap;
  transform: translateX(-50%);
}

.x-slot:first-child .x-label {
  left: 0;
  transform: none;
}

.x-slot:last-child .x-label {
  right: 0;
  left: auto;
  transform: none;
}

.x-label--now {
  color: var(--text-2);
}

.chart-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 9px;
  padding-top: 8px;
  border-top: 1px solid var(--border-soft);
}

.legend {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--muted);
  font-size: 9.5px;
}

.legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}

.swatch {
  width: 7px;
  height: 7px;
  border-radius: 1px;
}

.swatch--load {
  background: rgba(90, 162, 247, 0.55);
}

.swatch--cap {
  background: rgba(227, 173, 82, 0.7);
}

.chart-hint {
  color: var(--faint);
  font-size: 9px;
  white-space: nowrap;
}

.chart-hint kbd {
  margin-right: 2px;
}

/* ==========================================================================
   Workspace: incidents + detail
   ========================================================================== */

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 12px;
  align-items: start;
}

.incidents {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.incidents-head {
  min-height: 58px;
}

.severity-tally {
  display: flex;
  align-items: center;
  gap: 11px;
  flex: none;
}

.tally {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  white-space: nowrap;
}

.tally i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--sev);
}

/* Filters */

.table-tools {
  display: grid;
  grid-template-columns: minmax(190px, 1fr) auto auto auto auto;
  align-items: center;
  gap: 7px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--border);
  background: #0f141a;
}

.search-field {
  position: relative;
  display: flex;
  align-items: center;
  min-width: 0;
  height: 30px;
  border: 1px solid var(--border);
  border-radius: 3px;
  background: #0b1015;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.search-field:focus-within {
  border-color: var(--accent-line);
  box-shadow: 0 0 0 2px var(--accent-dim);
}

.search-field > .icon {
  position: absolute;
  left: 8px;
  color: var(--faint);
  pointer-events: none;
}

.search-field input {
  width: 100%;
  height: 100%;
  min-width: 0;
  padding: 0 30px 0 27px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 11px;
}

.search-field input::placeholder {
  color: var(--faint);
}

.search-field input::-webkit-search-cancel-button {
  -webkit-appearance: none;
}

.search-key {
  position: absolute;
  right: 6px;
  color: var(--faint);
  pointer-events: none;
}

.select-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.select-wrap select {
  width: 100%;
  height: 30px;
  padding: 0 24px 0 9px;
  border: 1px solid var(--border);
  border-radius: 3px;
  outline: 0;
  appearance: none;
  -webkit-appearance: none;
  background: #0b1015;
  color: var(--text-2);
  font-size: 10.5px;
  cursor: pointer;
  transition: border-color 120ms ease, color 120ms ease;
}

.select-wrap select:hover {
  border-color: var(--border-strong);
  color: var(--text);
}

.select-wrap select:focus-visible {
  border-color: var(--accent-line);
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.select-wrap option {
  background: #151b23;
  color: var(--text);
}

.select-wrap > .icon {
  position: absolute;
  right: 7px;
  color: var(--faint);
  pointer-events: none;
}

.clear-btn {
  height: 30px;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: 3px;
  background: transparent;
  color: var(--muted);
  font-size: 10.5px;
  white-space: nowrap;
  transition: color 110ms ease, background-color 110ms ease;
}

.clear-btn:hover:not(:disabled) {
  background: var(--surface-2);
  color: var(--text);
}

.clear-btn:disabled {
  opacity: 0.35;
  cursor: default;
}

/* Table */

.table-wrap {
  position: relative;
  min-width: 0;
}

.incident-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.col-severity { width: 88px; }
.col-service { width: 114px; }
.col-age { width: 62px; }
.col-owner { width: 108px; }
.col-status { width: 100px; }

.incident-table thead th {
  height: 29px;
  padding: 0 10px;
  border-bottom: 1px solid var(--border);
  background: #0e1319;
  color: var(--muted);
  font-weight: 500;
  text-align: left;
  vertical-align: middle;
}

.incident-table thead th:first-child {
  padding-left: 12px;
  border-left: 2px solid transparent;
}

.sort-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  width: 100%;
  height: 29px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.sort-btn:hover {
  color: var(--text-2);
}

.sort-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -4px;
}

.th-right .sort-btn {
  justify-content: flex-end;
  text-align: right;
}

.sort-ind {
  display: inline-flex;
  width: 8px;
  color: var(--accent);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0;
}

.incident-table th[aria-sort="ascending"] .sort-ind::after { content: "↑"; }
.incident-table th[aria-sort="descending"] .sort-ind::after { content: "↓"; }
.incident-table th[aria-sort="none"] .sort-ind::after { content: ""; }

.incident-table th[aria-sort="ascending"] .sort-btn,
.incident-table th[aria-sort="descending"] .sort-btn {
  color: var(--text-2);
}

.incident-row {
  --sev: var(--sev-low);
}

.incident-row td {
  height: 47px;
  padding: 5px 10px;
  border-bottom: 1px solid var(--border-soft);
  vertical-align: middle;
  overflow: hidden;
}

.incident-row:last-child td {
  border-bottom: 0;
}

.incident-row td:first-child {
  padding-left: 12px;
  border-left: 2px solid var(--sev);
}

.incident-row:hover {
  background: #141b23;
}

.incident-row.is-selected {
  background: rgba(90, 162, 247, 0.075);
}

.incident-row.is-selected td:last-child {
  box-shadow: inset -2px 0 0 var(--accent);
}

.incident-row:focus-within {
  background: #17202a;
}

.incident-row.is-selected:focus-within {
  background: rgba(90, 162, 247, 0.1);
}

.cell-severity {
  white-space: nowrap;
}

.sev-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--sev);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.055em;
  text-transform: uppercase;
  white-space: nowrap;
}

.sev-dot {
  width: 5px;
  height: 5px;
  flex: none;
  border-radius: 50%;
  background: var(--sev);
}

.sev-critical { --sev: var(--sev-critical); }
.sev-high { --sev: var(--sev-high); }
.sev-medium { --sev: var(--sev-medium); }
.sev-low { --sev: var(--sev-low); }

.cell-incident {
  min-width: 0;
}

.row-open {
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.row-open:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 2px;
}

.incident-id {
  display: block;
  overflow: hidden;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.02em;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.incident-title {
  display: block;
  overflow: hidden;
  color: var(--text-2);
  font-size: 11.5px;
  font-weight: 500;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.incident-row.is-selected .incident-title {
  color: var(--text);
}

.cell-service {
  overflow: hidden;
  color: #a8b4c1;
  font-family: var(--mono);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cell-age {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  text-align: right;
  white-space: nowrap;
}

.th-right {
  text-align: right;
}

.cell-owner {
  min-width: 0;
}

.owner-cell {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.owner-cell .avatar {
  width: 17px;
  height: 17px;
  border-radius: 3px;
  font-size: 7px;
}

.owner-name {
  overflow: hidden;
  color: var(--text-2);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.owner-cell--empty .avatar {
  border-style: dashed;
  color: var(--faint);
  background: transparent;
}

.owner-cell--empty .owner-name {
  color: var(--faint);
  font-style: italic;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 100%;
  height: 20px;
  padding: 0 6px;
  border: 1px solid #29333f;
  border-radius: 3px;
  background: rgba(21, 27, 35, 0.75);
  color: var(--text-2);
  font-size: 9.5px;
  white-space: nowrap;
}

.status-pill .status-dot {
  width: 4px;
  height: 4px;
  box-shadow: none;
  animation: none;
  background: var(--muted);
}

.status--open .status-dot { background: #8d99a6; }
.status--investigating .status-dot { background: var(--accent); }
.status--monitoring .status-dot { background: var(--teal); }
.status--acknowledged .status-dot { background: var(--good); }
.status--resolved .status-dot { background: #5d6875; }

.status--investigating {
  border-color: rgba(90, 162, 247, 0.28);
  color: #b8d5fb;
}

.status--monitoring {
  border-color: rgba(86, 194, 177, 0.24);
  color: #a9d9d1;
}

.status--acknowledged {
  border-color: rgba(78, 195, 140, 0.24);
  color: #b2ddc9;
}

.status--resolved {
  color: var(--faint);
}

.status--resolved .status-dot {
  background: #5d6875;
}

/* Empty and footer */

.table-empty {
  padding: 46px 24px 48px;
  text-align: center;
}

.empty-icon {
  display: inline-grid;
  place-items: center;
  width: 40px;
  height: 40px;
  margin-bottom: 11px;
  border: 1px dashed #303b48;
  border-radius: 4px;
  color: var(--faint);
  background: #0e1319;
}

.empty-icon .icon {
  width: 18px;
  height: 18px;
}

.table-empty h3 {
  color: var(--text-2);
  font-size: 12.5px;
  font-weight: 600;
}

.table-empty p {
  max-width: 320px;
  margin: 5px auto 14px;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.5;
}

.table-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: auto;
  padding: 8px 16px;
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: 10px;
}

.result-count strong {
  color: var(--text-2);
  font-family: var(--mono);
  font-weight: 500;
}

.key-hints {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--faint);
  font-size: 9px;
  white-space: nowrap;
}

.key-hints span {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.key-hints kbd {
  margin-right: 1px;
}

.touch-hint {
  display: none;
  color: var(--faint);
  font-size: 9px;
}

/* ==========================================================================
   Detail panel
   ========================================================================== */

.detail {
  position: sticky;
  top: calc(var(--topbar-h) + 12px);
  align-self: start;
  max-height: calc(100vh - var(--topbar-h) - 24px);
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: #303b48 transparent;
}

.detail::-webkit-scrollbar {
  width: 8px;
}

.detail::-webkit-scrollbar-thumb {
  border: 2px solid var(--surface);
  border-radius: 6px;
  background: #303b48;
}

.detail-empty {
  padding: 44px 24px 48px;
  text-align: center;
}

.detail-empty .empty-icon {
  margin-bottom: 12px;
}

.detail-empty h2 {
  color: var(--text-2);
  font-size: 13px;
  font-weight: 600;
}

.detail-empty p {
  max-width: 250px;
  margin: 5px auto 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.55;
}

.detail-empty .empty-kbd {
  margin-top: 14px;
  color: var(--faint);
  font-size: 9px;
}

.empty-kbd kbd {
  margin: 0 1px;
}

.detail-content {
  min-width: 0;
}

.detail-head {
  padding: 14px 15px 12px;
  border-bottom: 1px solid var(--border);
}

.detail-topline {
  display: flex;
  align-items: center;
  gap: 8px;
}

.detail-id {
  color: var(--faint);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.02em;
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 3px;
  background: transparent;
  color: var(--muted);
}

.icon-btn:hover {
  border-color: var(--border-strong);
  background: var(--surface-2);
  color: var(--text);
}

.detail-close {
  display: none;
  margin-left: auto;
}

.detail-title {
  margin: 9px 0 8px;
  color: var(--text);
  font-size: 15.5px;
  font-weight: 600;
  letter-spacing: -0.015em;
  line-height: 1.32;
  overflow-wrap: anywhere;
}

.detail-title:focus {
  outline: none;
}

.detail-state {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.detail-age {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
}

.detail-actions {
  display: flex;
  gap: 7px;
  padding: 11px 15px 8px;
}

.detail-actions .btn {
  height: 30px;
}

.detail-actions .btn-primary {
  flex: 1;
}

.ack-note {
  padding: 0 15px 13px;
  color: var(--faint);
  font-size: 9.5px;
  line-height: 1.45;
}

.ack-note--done {
  color: #8fc7aa;
}

.meta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 11px 14px;
  padding: 13px 15px;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.meta-grid dt {
  color: var(--faint);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.meta-grid dd {
  margin-top: 2px;
  overflow: hidden;
  color: var(--text-2);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.meta-grid dd.mono {
  font-family: var(--mono);
  font-size: 9.5px;
}

.meta-owner {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}

.meta-owner .avatar {
  width: 16px;
  height: 16px;
  border-radius: 3px;
  font-size: 6.5px;
}

.impact-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-bottom: 1px solid var(--border);
}

.impact-cell {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  padding: 10px 15px 11px;
}

.impact-cell + .impact-cell {
  border-left: 1px solid var(--border);
}

.impact-label {
  color: var(--faint);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.impact-value {
  overflow: hidden;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.timeline {
  padding: 13px 15px 16px;
}

.timeline-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.timeline-head h3 {
  color: var(--muted);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.timeline-count {
  color: var(--faint);
  font-family: var(--mono);
  font-size: 8.5px;
}

.timeline-list {
  position: relative;
  margin-top: 11px;
}

.timeline-list::before {
  content: "";
  position: absolute;
  top: 4px;
  bottom: 16px;
  left: 3px;
  width: 1px;
  background: #25303c;
}

.timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 9px minmax(0, 1fr);
  gap: 9px;
  padding-bottom: 13px;
}

.timeline-item:last-child {
  padding-bottom: 2px;
}

.timeline-dot {
  position: relative;
  z-index: 1;
  width: 7px;
  height: 7px;
  margin-top: 4px;
  border: 2px solid var(--surface);
  border-radius: 50%;
  background: #566373;
  box-shadow: 0 0 0 1px #566373;
}

.timeline-item:first-child .timeline-dot {
  background: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.timeline-item--ack .timeline-dot {
  background: var(--good);
  box-shadow: 0 0 0 1px var(--good);
}

.timeline-text {
  color: var(--text-2);
  font-size: 10.5px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.timeline-text strong {
  color: var(--text);
  font-weight: 500;
}

.timeline-time {
  display: block;
  margin-top: 1px;
  color: var(--faint);
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1.5;
}

.main-foot {
  margin-top: 14px;
  color: #4f5a67;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.02em;
  text-align: right;
}

/* ==========================================================================
   Toast + sheet backdrop
   ========================================================================== */

.toast {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 120;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  max-width: 330px;
  padding: 9px 12px;
  border: 1px solid #364352;
  border-left: 2px solid var(--good);
  border-radius: 3px;
  background: #1b242e;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.42);
  color: var(--text-2);
  font-size: 10.5px;
  line-height: 1.45;
  opacity: 0;
  pointer-events: none;
  transform: translateY(6px);
  transition: opacity 140ms ease, transform 140ms ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.toast-icon {
  display: inline-grid;
  place-items: center;
  color: var(--good);
  margin-top: 1px;
}

.sheet-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: rgba(4, 7, 10, 0.62);
}

/* ==========================================================================
   Responsive — narrow desktop and tablet
   ========================================================================== */

@media (max-width: 1159px) {
  .shell {
    grid-template-columns: 60px minmax(0, 1fr);
  }

  .rail {
    padding: 10px 8px 8px;
  }

  .rail-label {
    height: 1px;
    margin: 12px 6px;
    overflow: hidden;
    color: transparent;
    background: #1a222b;
    font-size: 0;
  }

  .rail-label:first-child {
    margin-top: 4px;
  }

  .rail-item {
    justify-content: center;
    gap: 0;
    padding: 0;
  }

  .rail-text,
  .rail-foot-text {
    display: none;
  }

  .rail-badge {
    position: absolute;
    top: 3px;
    right: 3px;
    min-width: 13px;
    height: 13px;
    padding: 0 3px;
    border-radius: 7px;
    font-size: 7.5px;
  }

  .rail-foot {
    justify-content: center;
    padding: 10px 0 2px;
  }

  .rail-group-system {
    margin-top: 12px;
  }
}

@media (max-width: 1249px) {
  .workspace {
    grid-template-columns: minmax(0, 1fr) 316px;
  }
}

@media (max-width: 1059px) {
  .workspace {
    grid-template-columns: minmax(0, 1fr);
  }

  .detail {
    position: static;
    max-height: none;
    overflow: visible;
  }

  .detail-empty {
    padding: 30px 24px;
  }

  .detail-content {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    column-gap: 0;
  }

  .detail-head,
  .detail-actions,
  .ack-note {
    grid-column: 1;
  }

  .detail-head {
    padding-bottom: 0;
    border-bottom: 0;
  }

  .meta-grid {
    grid-column: 1;
  }

  .impact-row {
    grid-column: 1;
    border-bottom: 1px solid var(--border);
  }

  .timeline {
    grid-column: 2;
    grid-row: 1 / span 5;
    border-left: 1px solid var(--border);
    padding: 14px 16px;
  }

  .timeline-list::before {
    bottom: 18px;
  }
}

@media (max-width: 1000px) {
  .operator-name,
  .brand-tag {
    display: none;
  }

  main {
    padding: 16px 16px 26px;
  }

  .severity-tally {
    display: none;
  }
}

@media (max-width: 900px) {
  .environment {
    display: none;
  }

  .metric-value {
    font-size: 23px;
  }

  .metric {
    padding: 12px 13px 11px;
  }

  .spark {
    width: 50px;
  }

