const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const DIR = __dirname;
const URL = 'file://' + path.join(DIR, '..', 'index.html');
const chrome = spawn('google-chrome-stable', [
  '--headless=new', '--disable-gpu', '--no-sandbox', '--hide-scrollbars',
  '--no-first-run', '--no-default-browser-check',
  '--remote-debugging-pipe',
  '--user-data-dir=' + path.join(DIR, 'chrome-profile'),
  '--window-size=1440,1100',
  URL
], { stdio: ['ignore', 'ignore', 'inherit', 'pipe', 'pipe'] });

let nextId = 1;
const pending = new Map();
let buffer = '';
let sessionId = null;
const events = [];

chrome.stdio[4].setEncoding('utf8');
chrome.stdio[4].on('data', (chunk) => {
  buffer += chunk;
  let index;
  while ((index = buffer.indexOf('\0')) !== -1) {
    const raw = buffer.slice(0, index);
    buffer = buffer.slice(index + 1);
    if (!raw) continue;
    let message;
    try { message = JSON.parse(raw); } catch (e) { console.error('parse', e, raw.slice(0, 200)); continue; }
    if (message.id && pending.has(message.id)) {
      const resolve = pending.get(message.id);
      pending.delete(message.id);
      resolve(message);
    } else {
      events.push(message);
    }
  }
});

function send(method, params = {}, sid) {
  return new Promise((resolve) => {
    const id = nextId++;
    pending.set(id, resolve);
    const payload = { id, method, params };
    if (sid) payload.sessionId = sid;
    chrome.stdio[3].write(JSON.stringify(payload) + '\0');
  });
}

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function evaluate(expression) {
  const response = await send('Runtime.evaluate', {
    expression,
    returnByValue: true,
    awaitPromise: true
  }, sessionId);
  if (response.result && response.result.exceptionDetails) {
    throw new Error(JSON.stringify(response.result.exceptionDetails));
  }
  return response.result && response.result.result ? response.result.result.value : undefined;
}

async function shot(name, full) {
  const response = await send('Page.captureScreenshot', {
    format: 'png',
    captureBeyondViewport: Boolean(full),
    fromSurface: true
  }, sessionId);
  if (!response.result || !response.result.data) {
    console.error('screenshot failed', JSON.stringify(response).slice(0, 300));
    return;
  }
  fs.writeFileSync(path.join(DIR, name), Buffer.from(response.result.data, 'base64'));
}

async function main() {
  await wait(1200);
  const targets = await send('Target.getTargets');
  const page = targets.result.targetInfos.find((t) => t.type === 'page');
  if (!page) throw new Error('no page target');
  const attach = await send('Target.attachToTarget', { targetId: page.targetId, flatten: true });
  sessionId = attach.result.sessionId;
  await send('Page.enable', {}, sessionId);
  await send('Runtime.enable', {}, sessionId);
  await send('Log.enable', {}, sessionId);

  await wait(1400);

  const report = {};

  report.desktop = await evaluate(`(() => ({
    innerWidth, innerHeight,
    pageScrollWidth: document.documentElement.scrollWidth,
    bodyScrollWidth: document.body.scrollWidth,
    rows: document.querySelectorAll('.incident-row').length,
