const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const DIR = __dirname;
const URL = 'file://' + path.join(DIR, '..', 'index.html');
const chrome = spawn('google-chrome-stable', [
  '--headless=new', '--disable-gpu', '--no-sandbox', '--hide-scrollbars',
  '--no-first-run', '--no-default-browser-check', '--remote-debugging-pipe',
  '--user-data-dir=' + path.join(DIR, 'chrome-profile-visual'),
  '--window-size=1440,1100', URL
], { stdio: ['ignore', 'ignore', 'inherit', 'pipe', 'pipe'] });

let nextId = 1;
const pending = new Map();
let buffer = '';
let sessionId = null;

chrome.stdio[4].setEncoding('utf8');
chrome.stdio[4].on('data', (chunk) => {
  buffer += chunk;
  let index;
  while ((index = buffer.indexOf('\0')) !== -1) {
    const raw = buffer.slice(0, index);
    buffer = buffer.slice(index + 1);
    if (!raw) continue;
    const message = JSON.parse(raw);
    if (message.id && pending.has(message.id)) {
      const resolve = pending.get(message.id);
      pending.delete(message.id);
      resolve(message);
    }
  }
});

function send(method, params = {}, sid) {
  return new Promise((resolve) => {
    const id = nextId++;
    pending.set(id, resolve);
    const payload = { id, method, params };
    if (sid) payload.sessionId = sid;
    chrome.stdio[3].write(JSON.stringify(payload) + '\0');
  });
}
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function evaluate(expression) {
  const response = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }, sessionId);
  if (response.result && response.result.exceptionDetails) throw new Error(JSON.stringify(response.result.exceptionDetails));
  return response.result && response.result.result ? response.result.result.value : undefined;
}

async function shot(name) {
  const response = await send('Page.captureScreenshot', { format: 'png', fromSurface: true }, sessionId);
  fs.writeFileSync(path.join(DIR, name), Buffer.from(response.result.data, 'base64'));
}

async function main() {
  await wait(1300);
  const targets = await send('Target.getTargets');
  const page = targets.result.targetInfos.find((t) => t.type === 'page');
  const attach = await send('Target.attachToTarget', { targetId: page.targetId, flatten: true });
  sessionId = attach.result.sessionId;
  await send('Page.enable', {}, sessionId);
  await send('Runtime.enable', {}, sessionId);
  await wait(1200);

  const report = {};
  const rect = await evaluate(`(() => {
    const bar = document.querySelectorAll('.bar-col')[19];
    const r = bar.getBoundingClientRect();
    return { x: r.x, y: r.y, w: r.width, h: r.height, label: bar.getAttribute('aria-label') };
  })()`);
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: rect.x + rect.w / 2, y: rect.y + rect.h / 2 }, sessionId);
  await wait(250);
  report.tooltip = await evaluate(`(() => {
    const tip = document.querySelectorAll('.bar-col')[19].querySelector('.bar-tip');
    return { opacity: getComputedStyle(tip).opacity, text: tip.textContent, bar: document.querySelectorAll('.bar-col')[19].getAttribute('aria-label') };
  })()`);
  await shot('chart-hover.png');

  await evaluate(`document.querySelector('.row-open').focus()`);
  report.focusVisible = await evaluate(`(() => ({
    matches: document.querySelector('.row-open').matches(':focus-visible'),
    active: document.activeElement.className
  }))()`);
  await evaluate(`document.querySelector('#incidents').scrollIntoView({block:'start'})`);
  await wait(250);
  await shot('row-focus.png');

  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true }, sessionId);
  await send('Page.reload', {}, sessionId);
  await wait(1000);
  await evaluate(`document.querySelector('#incidents').scrollIntoView({block:'start'})`);
  await wait(200);
  await evaluate(`document.querySelector('tr[data-id="INC-2839"] .row-open').focus()`);
  report.mobileFocus = await evaluate(`(() => ({
    matches: document.querySelector('tr[data-id="INC-2839"] .row-open').matches(':focus-visible'),
    active: document.activeElement.className,
    scrollWidth: document.documentElement.scrollWidth
  }))()`);
  await shot('mobile-row-focus.png');

  await evaluate(`document.querySelector('tr[data-id="INC-2839"]').click()`);
  await wait(400);
  await evaluate(`document.getElementById('detailPanel').scrollTop = 900`);
  await wait(200);
  report.sheetScroll = await evaluate(`(() => {
    const head = document.querySelector('.detail-head').getBoundingClientRect();
    const close = document.getElementById('closeDetail').getBoundingClientRect();
    const panel = document.getElementById('detailPanel');
    return { scrollTop: panel.scrollTop, headTop: head.top, closeTop: close.top, closeVisible: close.bottom <= innerHeight };
  })()`);
  await shot('mobile-sheet-scrolled.png');

  console.log(JSON.stringify(report, null, 2));
  chrome.kill('SIGTERM');
  setTimeout(() => process.exit(0), 300);
}

main().catch((error) => {
  console.error(error);
  chrome.kill('SIGTERM');
  setTimeout(() => process.exit(1), 300);
});

