const { spawn } = require('child_process');
const path = require('path');
const URL = 'file://' + path.join(__dirname, '..', 'index.html');
const chrome = spawn('google-chrome-stable', ['--headless=new','--disable-gpu','--no-sandbox','--hide-scrollbars','--remote-debugging-pipe','--user-data-dir='+path.join(__dirname,'cp-widths'),'--window-size=1440,1000',URL], {stdio:['ignore','ignore','inherit','pipe','pipe']});
let id=1; const pending=new Map(); let buf=''; let sid=null;
chrome.stdio[4].setEncoding('utf8'); chrome.stdio[4].on('data',c=>{buf+=c;let i;while((i=buf.indexOf('\0'))>=0){const raw=buf.slice(0,i);buf=buf.slice(i+1);if(!raw)continue;const m=JSON.parse(raw);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}}});
function send(method,params={},sessionId){return new Promise(r=>{const n=id++;pending.set(n,r);const p={id:n,method,params};if(sessionId)p.sessionId=sessionId;chrome.stdio[3].write(JSON.stringify(p)+'\0');});}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function ev(expression){const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true},sid);if(r.result&&r.result.exceptionDetails)throw new Error(JSON.stringify(r.result.exceptionDetails));return r.result&&r.result.result?r.result.result.value:r;}
(async()=>{await wait(1200);const t=await send('Target.getTargets');const page=t.result.targetInfos.find(x=>x.type==='page');sid=(await send('Target.attachToTarget',{targetId:page.targetId,flatten:true})).result.sessionId;await send('Page.enable',{},sid);await send('Runtime.enable',{},sid);await wait(800);
const widths=[320,360,390,414,600,760,768,820,900,1024,1060,1159,1200,1280,1366,1440,1680];
const out=[];
for(const w of widths){
  await send('Emulation.setDeviceMetricsOverride',{width:w,height:900,deviceScaleFactor:1,mobile:w<760},sid);
  await wait(220);
  out.push(await ev(`(() => {
    const offenders=[...document.querySelectorAll('body *')].filter(el=>{
      const r=el.getBoundingClientRect();
      const s=getComputedStyle(el);
      if(r.width<1||r.height<1) return false;
      if(s.position==='fixed') return false;
      if(el.closest('.bar-tip')) return false;
      return r.right>innerWidth+1 || r.left<-1;
    }).slice(0,6).map(el=>el.className||el.tagName);
    return {
      w:innerWidth,
      sw:document.documentElement.scrollWidth,
      bsw:document.body.scrollWidth,
      tableRight:Math.round(document.querySelector('.incident-table').getBoundingClientRect().right),
      detailPos:getComputedStyle(document.getElementById('detailPanel')).position,
      railPos:getComputedStyle(document.querySelector('.rail')).position,
      offenders
    };
  })()`));
}
console.log(JSON.stringify(out,null,1));
chrome.kill('SIGTERM'); setTimeout(()=>process.exit(0),200);
})().catch(e=>{console.error(e);chrome.kill('SIGTERM');process.exit(1)});
